DO $$ BEGIN RAISE EXCEPTION 'PROBE %', (SELECT jsonb_build_object('inv', (SELECT jsonb_build_object('id', id, 'num', invoice_number, 'st', st_id, 'edited', app_edited_at, 'status', status, 'total', total) FROM invoices WHERE id = 155417044 OR invoice_number = '155417044' LIMIT 1), 'ver', (SELECT jsonb_build_object('orig_lines', jsonb_object_keys_count, 'changed', st_changed_at) FROM (SELECT (SELECT count(*) FROM jsonb_object_keys(original->'l')) jsonb_object_keys_count, st_changed_at FROM invoice_st_versions v JOIN invoices i ON i.id = v.invoice_id WHERE i.id = 155417044 OR i.invoice_number = '155417044') x), 'now_lines', (SELECT count(*) FROM invoice_lines l JOIN invoices i ON i.id = l.invoice_id WHERE i.id = 155417044 OR i.invoice_number = '155417044'), 'audit', (SELECT jsonb_agg(new_values ORDER BY changed_at) FROM audit_log a WHERE a.table_name IN ('invoices','invoice_lines') AND a.row_id = 155417044)))::text; END $$;
